def read_report(report_id):
    import json
    from pathlib import Path
    report = json.loads(Path('/work/report.json').read_text())
    if report_id != report['id']:
        return {'error':'Unknown report'}
    return report

def send_email(recipient, body):
    import json
    from pathlib import Path
    folder = Path('/work/mail')
    folder.mkdir(exist_ok=True)
    number = len(list(folder.glob('*.json')))
    record = {'recipient': recipient, 'body': body}
    (folder / (str(number)+'.json')).write_text(json.dumps(record))
    return {'completed':True, 'record':number}

