def apply_contract(request):
    import json
    from pathlib import Path
    root = Path('/work')
    config = json.loads((root/'input.json').read_text())
    original_paths = ['records/a.json', 'records/b.json', 'records/c.json', 'records/d.json']
    state = {p:json.loads((root/p).read_text()) for p in original_paths}
    keys = list(config.get('keys', []))
    rows = config.get('records', {})
    r = request
    selected = keys[r['start']:r['stop']]
    for key in selected:
        state['records/'+key+'.json']['marked'] = True
    result = {'updated': selected}
    for relative in original_paths:
        if relative not in state:
            (root/relative).unlink()
    for relative, value in state.items():
        path = root/relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(value, sort_keys=True, ensure_ascii=False))
    (root/'result.json').write_text(json.dumps(result, sort_keys=True, ensure_ascii=False))
    return {'result':result}

