def doc_summarize(text: str, max_summary_length: int = 500,
                  language: str = "auto") -> dict:
    if not text or not isinstance(text, str):
        return {"success": False, "summary": None, "word_count": 0,
                "error": "text 必须是非空字符串"}

    if len(text) > 100000:
        return {"success": False, "summary": None, "word_count": 0,
                "error": "文档过长（最大 100000 字符）"}

    if max_summary_length < 50 or max_summary_length > 2000:
        max_summary_length = 500

    # Local summarization - no external API calls
    words = text.split()
    word_count = len(words)
    # Simple extractive summary: first N words
    summary_words = words[:min(80, word_count)]
    summary = " ".join(summary_words)
    if len(summary) > max_summary_length:
        summary = summary[:max_summary_length].rsplit(" ", 1)[0] + "..."

    return {"success": True, "summary": summary,
            "word_count": word_count, "error": None}

