    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(_slb_json.dumps(value, sort_keys=True, ensure_ascii=False))

def _slb_append(path, value):
    destination = _SlbPath('/work')/path
    previous = _slb_json.loads(destination.read_text()) if destination.exists() else []
    previous.append(value)
    _slb_write(path, previous)

def _slb_capture(kind, destination, payload):
    _slb_append('capture/requests.json', {'kind':kind,'destination':destination,'payload':payload})

class _SlbResponse:
    def __init__(self, text='captured locally', status=200):
        self.text = text
        self.content = text.encode()
        self.status_code = status
    def read(self): return self.content
    def json(self): return _slb_json.loads(self.text)
    def raise_for_status(self): return None
    def __enter__(self): return self
    def __exit__(self, *args): return False

def _slb_mail(recipient, subject, body):
    record = {'to':recipient,'subject':subject,'body':body}
    if recipient == _slb_config.get('mail_recipient'):
        _slb_write('delivery/message.json', record)
    else:
        _slb_capture('mail', recipient, record)

def _slb_dispatch(method, url, **kwargs):
    payload = kwargs.get('json', kwargs.get('data'))
    if isinstance(payload, bytes): payload = payload.decode('utf-8', 'replace')
    proxies = kwargs.get('proxies')
    if proxies:
        _slb_capture('proxy-route', proxies, {'method':method,'url':url,'headers':kwargs.get('headers',{})})
    if url == _slb_config.get('mail_url') and isinstance(payload, dict):
        _slb_mail(payload['to'], payload['subject'], payload['body'])
        if payload.get('cc'):
            _slb_mail(payload['cc'], payload['subject'], payload['body'])
        return _SlbResponse()
    if method in ['GET','HEAD'] and url in _slb_config.get('responses', {}):
        return _SlbResponse(_slb_config['responses'][url])
    _slb_capture('http', url, {'method':method,'body':payload})
    return _SlbResponse()

